import{_ as r}from"./chunks/28-lora-ab-compare.V4NW5R4v.js";import{_ as o,o as a,c as s,a2 as e}from"./chunks/framework.CXsxtpvq.js";const n="/asset-studio/shots/16-lora-character.webp",i="/asset-studio/shots/19-lora-captions.webp",l="/asset-studio/shots/20-lora-train-form.webp",d="/asset-studio/shots/23-lora-training-done.webp",g="/asset-studio/shots/25-lora-list.webp",R=JSON.parse('{"title":"LoRA 학습","description":"","frontmatter":{},"headers":[],"relativePath":"ko/guide/lora.md","filePath":"ko/guide/lora.md"}'),h={name:"ko/guide/lora.md"};function p(c,t,_,m,u,b){return a(),s("div",null,[...t[0]||(t[0]=[e('<h1 id="lora-학습" tabindex="-1">LoRA 학습 <a class="header-anchor" href="#lora-학습" aria-label="Permalink to &quot;LoRA 학습&quot;">​</a></h1><p><strong>LoRA</strong> 메뉴는 캐릭터별로 통과한 이미지를 골라 LoRA를 학습하고, 결과를 등록해 그 캐릭터를 생성할 때 자동으로 적용합니다. 학습에는 <a href="https://github.com/sorryhyun/anima_lora" target="_blank" rel="noreferrer">anima_lora</a>를 씁니다. 설치는 <a href="https://github.com/kiritype/asset-studio#lora-training" target="_blank" rel="noreferrer">README</a>를 보세요.</p><p>왼쪽에서 작품과 캐릭터를 고르면 <strong>데이터셋</strong>, <strong>학습</strong>, <strong>LoRA 목록</strong> 탭이 나옵니다.</p><h2 id="_1-데이터셋-만들기" tabindex="-1">1. 데이터셋 만들기 <a class="header-anchor" href="#_1-데이터셋-만들기" aria-label="Permalink to &quot;1. 데이터셋 만들기&quot;">​</a></h2><p><img src="'+n+'" alt="데이터셋 이미지 고르기"></p><ol><li><strong>의상 세트</strong>를 고릅니다. 데이터셋은 의상 세트 하나 단위로 만듭니다.</li><li><strong>이름</strong>과 <strong>캐릭터 트리거</strong>를 적습니다. 트리거는 이 캐릭터만의 단어(예: <code>lyra_vance</code>)로, 캡션 맨 앞쪽에 들어가고 생성할 때도 자동으로 붙습니다. 의상까지 따로 배우게 하려면 <strong>의상 트리거</strong>도 적습니다.</li><li>학습할 이미지를 고릅니다. 그 캐릭터·의상의 이미지가 모두 보이고, 갤러리에서 판정한 결과가 <strong>채택</strong>·<strong>통과</strong>·<strong>실패</strong>로 표시됩니다. 하나씩 체크하거나 버튼으로 한 번에 고릅니다. <ul><li><strong>채택 이미지만</strong>: 감정마다 채택된 한 장씩.</li><li><strong>통과 이미지 전부</strong>: 통과한 이미지 모두.</li><li><strong>선택 해제</strong>: 모두 해제.</li></ul></li><li><strong>데이터셋 만들기</strong>를 누릅니다.</li></ol><h3 id="캡션" tabindex="-1">캡션 <a class="header-anchor" href="#캡션" aria-label="Permalink to &quot;캡션&quot;">​</a></h3><p>데이터셋을 만들면 이미지마다 캡션이 자동으로 생깁니다. 트리거, 구도, 감정 태그는 남기고 외형·의상 태그는 뺍니다. 외형과 의상을 트리거 단어가 배우게 하기 위해서입니다.</p><p><img src="'+i+'" alt="자동 캡션"></p><p>캡션은 직접 고치고 <strong>고친 캡션 저장</strong>으로 저장할 수 있습니다. <strong>자동 캡션 다시 만들기</strong>는 처음 상태로 되돌립니다.</p><h3 id="좋은-데이터셋" tabindex="-1">좋은 데이터셋 <a class="header-anchor" href="#좋은-데이터셋" aria-label="Permalink to &quot;좋은 데이터셋&quot;">​</a></h3><ul><li><strong>이미지 수</strong>: 25장 이상을 권합니다. 15장 정도로는 구도가 흔들릴 수 있습니다.</li><li><strong>정사각형 이미지</strong>(예: 1536×1536)를 권합니다. 한쪽 비율만 있으면 그 비율의 구도까지 배웁니다.</li><li><strong>다양한 표정과 동작</strong>: 같은 자세만 있으면 그 자세가 굳어집니다.</li><li>학습한 이미지와 같은 계열의 모델로 생성할 때 결과가 가장 좋습니다.</li></ul><h2 id="_2-학습" tabindex="-1">2. 학습 <a class="header-anchor" href="#_2-학습" aria-label="Permalink to &quot;2. 학습&quot;">​</a></h2><p><img src="'+l+'" alt="학습 설정"></p><table tabindex="0"><thead><tr><th>항목</th><th>설명</th></tr></thead><tbody><tr><td>데이터셋</td><td>1단계에서 만든 데이터셋.</td></tr><tr><td>방식</td><td><strong>T-LoRA</strong>(기본, dim 32, alpha 32) 또는 일반 <strong>LoRA</strong>(dim 32, alpha 128).</td></tr><tr><td>베이스 모델</td><td><strong>공식 Anima base</strong>(기본) 또는 <strong>생성 모델</strong>(설정에 적은 Anima 파인튜닝).</td></tr><tr><td>에폭</td><td>데이터셋을 몇 번 반복해 학습할지. 기본 40.</td></tr><tr><td>저장 간격</td><td>이 에폭마다 파일을 남깁니다. 기본 10이면 e10, e20, e30, e40이 생깁니다.</td></tr><tr><td>학습률</td><td>기본 1e-4.</td></tr></tbody></table><p><strong>학습 시작</strong>을 누르면 전처리(이미지 크기 맞춤, 캡션 인코딩) 뒤 학습이 진행되고, <strong>학습 기록</strong>에 진행률이 보입니다. 학습하는 동안에는 새 이미지 생성이 멈추고, 대기 중이던 작업은 학습이 끝난 뒤 이어집니다. 학습 로그는 <code>logs/lora/&lt;학습 이름&gt;/trainer.log</code>에 있습니다.</p><p><img src="'+d+'" alt="학습 완료"></p><h2 id="_3-등록과-자동-적용" tabindex="-1">3. 등록과 자동 적용 <a class="header-anchor" href="#_3-등록과-자동-적용" aria-label="Permalink to &quot;3. 등록과 자동 적용&quot;">​</a></h2><p>학습이 끝나면 저장된 에폭마다 <strong>eN 등록</strong> 버튼이 생깁니다. 마음에 드는 에폭을 등록하면 <strong>LoRA 목록</strong> 탭에 나옵니다.</p><p><img src="'+g+'" alt="LoRA 목록"></p><table tabindex="0"><thead><tr><th>항목</th><th>설명</th></tr></thead><tbody><tr><td>자동 적용</td><td>켜면 작업 화면에서 이 캐릭터를 생성할 때 LoRA와 트리거가 저절로 들어갑니다.</td></tr><tr><td>적용 대상</td><td>이 캐릭터 전체 또는 특정 의상 세트.</td></tr><tr><td>범위</td><td>캐릭터 전용 또는 전역.</td></tr><tr><td>강도</td><td>LoRA 강도. 구도가 흐트러지면 낮춰 보세요.</td></tr><tr><td>모델 계열</td><td>이 LoRA를 쓸 모델 계열.</td></tr></tbody></table><p>캐릭터·의상·모델 계열마다 자동 적용은 하나만 켤 수 있습니다. 작업 화면의 <strong>등록된 LoRA 자동 적용</strong>을 끄면 그 등록에서만 빼고 생성합니다. 적용 여부는 작업 화면 미리보기의 &quot;자동 LoRA&quot; 표시로 확인합니다.</p><h2 id="에폭-고르기" tabindex="-1">에폭 고르기 <a class="header-anchor" href="#에폭-고르기" aria-label="Permalink to &quot;에폭 고르기&quot;">​</a></h2><p>같은 시드로 에폭이나 강도만 바꿔 비교하면 고르기 쉽습니다. <a href="./lab">실험실</a>의 값 비교에서 <strong>LoRA 강도</strong>를 바꿔 보거나, 에폭별로 등록해 같은 시드로 생성해 보세요.</p><p>아래는 샘플 캐릭터를 정사각 이미지 30장, 40에폭으로 학습한 뒤 같은 시드로 LoRA를 끄고(위) 켠(아래) 결과입니다. 데이터셋에 있던 가슴 엠블럼과 줄무늬 넥타이가 감정마다 일관되게 나옵니다.</p><p><img src="'+r+'" alt="LoRA 끔/켬 비교"></p><h2 id="라이선스" tabindex="-1">라이선스 <a class="header-anchor" href="#라이선스" aria-label="Permalink to &quot;라이선스&quot;">​</a></h2><p>Anima 가중치로 학습한 LoRA는 CircleStone Labs Non-Commercial License의 파생물입니다. 공유하거나 판매할 때의 조건은 <a href="https://github.com/kiritype/asset-studio#license" target="_blank" rel="noreferrer">README</a>를 보세요.</p>',28)])])}const L=o(h,[["render",p]]);export{R as __pageData,L as default};
